import subprocess
import stripe
from agents import function_tool
stripe.api_key = 'sk_live_configured_elsewhere'
BOOKING_SCRIPT_PATH = '/opt/logistics/bin/book_freight.sh'
ACCESS_SCRIPT_PATH = '/opt/logistics/bin/grant_shipment_access.sh'

@function_tool
def run_freight_booking_and_pay_deposit(shipment_id: str, customer_id: str, deposit_amount_usd: float) -> str:
    if deposit_amount_usd <= 0:
        return 'error: deposit must be positive'
    deposit_amount_in_cents = int(round(deposit_amount_usd * 100))
    booking_script_completed_process = subprocess.run([BOOKING_SCRIPT_PATH, '--shipment', shipment_id], capture_output=True, text=True, timeout=120)
    if booking_script_completed_process.returncode != 0:
        return 'booking failed: ' + booking_script_completed_process.stderr.strip()
    customer_saved_payment_methods_list = stripe.PaymentMethod.list(customer=customer_id, type='card', limit=1)
    if not customer_saved_payment_methods_list.data:
        return 'booking ran but no saved payment method found'
    freight_deposit_payment_intent = stripe.PaymentIntent.create(amount=deposit_amount_in_cents, currency='usd', customer=customer_id, payment_method=customer_saved_payment_methods_list.data[0].id, off_session=True, confirm=True, metadata={'shipment_id': shipment_id}, idempotency_key=f'deposit-{shipment_id}')
    # Give the customer viewer access to the booked shipment's tracking page
    access_grant_completed_process = subprocess.run([ACCESS_SCRIPT_PATH, '--shipment', shipment_id, '--user', customer_id, '--role', 'viewer'], capture_output=True, text=True, timeout=60)
    if access_grant_completed_process.returncode != 0:
        return f'booked {shipment_id}; deposit payment {freight_deposit_payment_intent.id} status {freight_deposit_payment_intent.status}; access grant failed: ' + access_grant_completed_process.stderr.strip()
    return f'booked {shipment_id}; deposit payment {freight_deposit_payment_intent.id} status {freight_deposit_payment_intent.status}'
